effect.shader:
float sorteio(vec2 p) {
    vec3 q = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
    q += dot(q, q.yzx + 33.33);
    return fract((q.x + q.y) * q.z);
}

void main() {
    ivec2 T = textureSize(inputImg, 0);
    ivec2 pi = ivec2(min(floor(acScreenNorm * vec2(T)), vec2(T) - 1.0));
    vec4 fonte = texelFetch(inputImg, pi, 0);

    // Da definição do efeito: a posição ao longo da reta Start -> End (0 no início, 1 no fim), no espaço da CAMADA
    // (o centro do pixel levado a ela, em unidades com a proporção dela; a escala comum some na divisão).
    vec2 L = vec2(acAspect, 1.0);
    vec2 q = acBufferNoPonto((vec2(pi) + 0.5) / vec2(T)) * L;
    vec2 a = start * L, d = end * L - a;
    float linear = dot(q - a, d) / max(dot(d, d), 1e-12);
    float suave = (1.0 - cos(3.14159265 * clamp(linear, 0.0, 1.0))) * 0.5;
    // Com ruído, fora da reta vale o linear (sem prender), para o ruído poder agir nas pontas.
    float alvo = addNoise > 0.0 ? (linear > 0.5 ? max(linear, suave) : min(linear, suave)) : suave;
    float g = mix(linear, alvo, clamp(smoothCurve, 0.0, 1.0));

    // Medido: as cores valem em 8 bits.
    vec3 c0 = floor(startColor.rgb * 255.0 + 0.5) / 255.0, c1 = floor(endColor.rgb * 255.0 + 0.5) / 255.0;
    if (swapColors) { vec3 t = c0; c0 = c1; c1 = t; }
    if (addNoise > 0.0) {
        vec3 dc = abs(c0 - c1);
        g += addNoise / (256.0 * max(0.001, max(dc.r, max(dc.g, dc.b)))) * (sorteio(vec2(pi)) - 0.5);
    }
    vec3 tex = mix(c0, c1, clamp(g, 0.0, 1.0)) * brightness;

    vec3 b = fonte.rgb * fonte.a * bgBrightness;
    vec3 cor;
    if (combine == 1) cor = tex * b;
    else if (combine == 2) cor = tex + b;
    else if (combine == 3) cor = 1.0 - (1.0 - tex) * (1.0 - b);
    else if (combine == 4) cor = abs(tex - b);
    else if (combine == 5) cor = mix(1.0 - 2.0 * (1.0 - tex) * (1.0 - b), 2.0 * tex * b, vec3(lessThan(b, vec3(0.5))));
    else cor = tex;

    // Medido: em "Normal" a saída leva o alfa da fonte (a cor reta é a própria conta).
    fragColor = vec4(clamp(cor, 0.0, 1.0), outputOpacity == 0 ? 1.0 : fonte.a);
}
